using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
class ActualUsageShapeTests {static IEnumerable<string> SharedLines(string path){using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream)){string line;while((line=reader.ReadLine())!=null)yield return line;}}static int Main(string[] args){int events=0,accepted=0;var store=new CodexUsageArchive(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"never-save-live-values"));try{foreach(string file in Directory.GetFiles(args[1],"rollout-*.jsonl").OrderByDescending(File.GetLastWriteTimeUtc).Take(3)){int fileEvents=0;foreach(string line in SharedLines(file)){if(!line.Contains("\"token_count\""))continue;var root=new JavaScriptSerializer{MaxJsonLength=8388608}.Deserialize<Dictionary<string,object>>(line);object kind,payload;if(!root.TryGetValue("type",out kind)||Convert.ToString(kind)!="event_msg"||!root.TryGetValue("payload",out payload))continue;var data=payload as Dictionary<string,object>;if(data==null||!data.TryGetValue("type",out kind)||Convert.ToString(kind)!="token_count")continue;events++;fileEvents++;if(store.Consume(line,Path.GetFileName(file)))accepted++;if(fileEvents>=100)break;}}bool ok=events>0&&accepted>0;Console.WriteLine((ok?"PASS ":"FAIL ")+"native parser accepts real local usage events without persisting content or totals");File.WriteAllText(Path.Combine(args[0],"actual-usage-schema.json"),new JavaScriptSerializer().Serialize(new{usage_events_checked=events,positive_deltas_accepted=accepted,passed=ok,real_log_files_modified=false,raw_events_saved=false,actual_token_totals_exported=false}));return ok?0:1;}catch(Exception e){Console.WriteLine("FAIL "+e.GetType().Name+" HRESULT="+e.HResult.ToString("X"));return 1;}}}
